<template>
  <minimal-layout>
    <v-container
      fluid
      fill-height
    >
      <v-layout
        align-center
        justify-center
      >
        <v-flex
          xs12
          sm6
          md4
        >
          <div style="text-align:center"><img :src="logoSrc" /></div>
          <div
            style="text-align:center"
            class="headline"
          >{{appSettings.nama_pt}}</div>
          <div
            style="text-align:center"
            class="subheading mb-2"
          >IT Inventory</div>
          <v-form>
            <v-card class="elevation-5">
              <v-card-text>
                <v-text-field
                  v-model="input.username"
                  prepend-icon="person"
                  name="Username"
                  label="Username"
                  type="text"
                  @keyup.enter.native="login()"
                  :error-messages="errors.collect('Username')"
                  v-validate="'required'"
                ></v-text-field>
                <v-text-field
                  v-model="input.password"
                  id="password"
                  prepend-icon="lock"
                  name="Password"
                  label="Password"
                  type="password"
                  @keyup.enter.native="login()"
                  :error-messages="errors.collect('Password')"
                  v-validate="'required'"
                ></v-text-field>
              </v-card-text>
              <v-divider></v-divider>
              <v-card-actions class="px-3 py-3">
                <v-btn
                  dark
                  color="primary"
                  @click="login()"
                >Login</v-btn>
              </v-card-actions>
            </v-card>
            <v-alert
              v-if="errorMessage"
              type="error"
              :value="errorMessage"
              class="mt-2"
            >
              {{errorMessage}}
            </v-alert>
          </v-form>
        </v-flex>
      </v-layout>
    </v-container>
  </minimal-layout>
</template>

<script>
import { API_LOCATION } from "@/constants";

export default {
  data() {
    return {
      logoSrc: `${API_LOCATION}image/get/sanwa`,
      input: {
        username: null,
        password: null
      },
      errorMessage: ""
    };
  },
  created() {
    window.eventBus.$on("LOGIN_ERROR", () => {
      this.errorMessage = "Invalid username and password";
    });
  },
  methods: {
    login() {
      this.$validator.validateAll().then(() => {
        if (!this.errors.any()) {
          this.errorMessage = false;
          this.$store.dispatch("auth/login", this.input);
        } else {
          $(`[name="${this.errors.items[0].field}"]`).focus();
        }
      });
    }
  },
  computed: {
    appSettings() {
      return this.$store.state.app.appSettings;
    }
  }
};
</script>



